# %% ../nbs/04_md_hier.ipynb #3575b8f2
_LINK_RE = re.compile(r'(?<!\!)\[([^\]]*)\]\(([^)\s]+)\)')

class Link:
    "One inline link, numbered in document reading order"
    def __init__(self,
        n,    # 1-based number, in document reading order
        txt,  # The link text
        url,  # The link target (never shown by `__repr__`; the number stands for it)
        tail, # The rest of the link's line, as context - an llms.txt entry's description
        line, # Document-absolute 1-based line number
    ): store_attr()
    def __repr__(self): return f'[{self.n}] {self.txt}' + (f': {self.tail}' if self.tail else '')

class Sections(L):
    "Sections listed as `addr title` rows; each row is the live node"
    def __init__(self, items=None, counts=None, **kw):
        super().__init__(items, **kw)
        self.counts = counts
    def __getitem__(self, idx):
        res = super().__getitem__(idx)
        return Sections(res) if isinstance(idx, slice) else res
    def __repr__(self):
        if self.counts: return '\n'.join(f'{n.addr or "."} {n.title} ({c})' for n,c in zip(self, self.counts))
        return '\n'.join(f'{n.addr or "."} {n.title}' for n in self)

# %% ../nbs/04_md_hier.ipynb #0ac961ea
class HeadingDict(dict):
    "A dictionary of numbered child sections, with the section Markdown in `text`."
    title,addr = '',''
    def __init__(self, src='', start_line=1, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.src,self.start_line = src,start_line

    @property
    def end_line(self):
        "Document-absolute 1-based line number of this section's last line."
        return self.start_line + len(self.src.splitlines()) - 1

    @property
    def text(self):
        "Section Markdown, with each parsed inline link rendered as `[text][n]`."
        links = getattr(getattr(self, 'root', None), '_links', None)
        if not links: return self.src
        res = []
        for i,line in enumerate(self.src.splitlines()):
            here = [l for l in links if l.line == self.start_line+i]
            if here:
                it = iter(here)
                line = _LINK_RE.sub(lambda m: f'[{m[1]}][{next(it).n}]', line)
            res.append(line)
        return '\n'.join(res)

    def _walk(self):
        for node in self.values():
            yield node
            yield from node._walk()

    def paths(self,
        depth=None, # Deepest address depth to include; None for all
    ):
        "Outline of every section as `addr title` rows; each row is the live node"
        ns = self._walk()
        if depth: ns = (n for n in ns if n.addr.count('.') < depth)
        return Sections(ns)

    def at(self, *path):
        "The node at `path`: a dotted address like `'1.4.5'` (resolved from the root), or key ints (resolved from here)"
        if len(path) == 1 and isinstance(path[0], str):
            node = self.root
            for k in path[0].split('.'): node = node[int(k)]
            return node
        node = self
        for k in path: node = node[k]
        return node

    def find(self, title):
        "The unique section titled `title`; raises if absent or ambiguous"
        ms = [n for n in self._walk() if n.title == title]
        if len(ms) != 1: raise KeyError(f"Expected one heading named {title!r}, found {len(ms)}: {[n.addr for n in ms]}")
        return ms[0]

    def refresh(self):
        "Fresh tree re-read from `path` (roots from `create_heading_dict_file` only)"
        return create_heading_dict_file(self.path)

    def view(self,
        nums=False, # Prefix lines with document-absolute line numbers, `lineno: `
        lnhashs=False # Prefix `lineno|hash|` exhash addresses instead; wins over `nums`
    ):
        "Source exactly as stored, links unnumbered, so an editor can address the source file directly"
        lines = self.src.splitlines()
        if lnhashs: return PrettyString('\n'.join(lnhash(self.start_line+i, l)+l for i,l in enumerate(lines)))
        if nums: return PrettyString('\n'.join(f'{self.start_line+i}: {l}' for i,l in enumerate(lines)))
        return self.src

# %% ../nbs/04_md_hier.ipynb #db2212b5
def create_heading_dict(text, rm_fenced=True, base=None):
    "Create a nested `HeadingDict` from Markdown headings, numbering sections and inline links in reading order."
    lines = text.splitlines()
    headings,links,fence = [],[],None
    for i,line in enumerate(lines):
        if match := re.match(r'^\s*(`{3,}|~{3,})', line):
            marker = match[1][0]
            if fence == marker: fence = None
            elif fence is None: fence = marker
            if rm_fenced: continue
        if fence and rm_fenced: continue
        if match := re.match(r'^(#{1,6})\s+(.+?)\s*#*\s*$', line):
            headings.append(dict(level=len(match[1]), title=match[2], line=i))
        ms = list(_LINK_RE.finditer(line))
        for j,m in enumerate(ms):
            tail = line[m.end() : ms[j+1].start() if j+1 < len(ms) else len(line)]
            links.append(Link(len(links)+1, m[1], m[2], tail.strip().lstrip(':').strip(), i+1))

    for i,heading in enumerate(headings):
        end = next((h['line'] for h in headings[i+1:] if h['level'] <= heading['level']), len(lines))
        heading['text'] = '\n'.join(lines[heading['line']:end]).strip()

    result = HeadingDict(text)
    result.root,result._links,result.base = result,links,base
    stack,levels = [result],[0]
    for heading in headings:
        while len(stack) > 1 and levels[-1] >= heading['level']:
            stack.pop()
            levels.pop()
        parent,k = stack[-1],len(stack[-1])+1
        parent[k] = node = HeadingDict(heading['text'], heading['line']+1)
        node.root,node.title = result,heading['title']
        node.addr = f'{parent.addr}.{k}' if parent.addr else str(k)
        stack.append(node)
        levels.append(heading['level'])
    return result

