@patch
def search(self:HeadingDict,
    pat, # Case-insensitive regex, matched line by line; an invalid regex matches literally
):
    "The deepest sections owning a line matching `pat`, in document order, with match counts"
    try: r = re.compile(pat, re.IGNORECASE)
    except re.error: r = re.compile(re.escape(pat), re.IGNORECASE)
    subtree = [self, *self._walk()]
    hits = {}
    for i,line in enumerate(self.src.splitlines()):
        if not r.search(line): continue
        ln = self.start_line + i
        own = max((n for n in subtree if n.start_line <= ln <= n.end_line), key=lambda n: (n.start_line, len(n.addr)))
        node,c = hits.get(id(own), (own, 0))
        hits[id(own)] = (node, c+1)
    return Sections([n for n,_ in hits.values()], counts=[c for _,c in hits.values()])

# %% ../nbs/04_md_hier.ipynb #f79f8f5b
def create_heading_dict_file(path, rm_fenced=True):
    "Create a `HeadingDict` from the Markdown file at `path` (`~` ok), recording `path` for `refresh` and as the `base` for `follow`"
    path = Path(path).expanduser()
    res = create_heading_dict(path.read_text(), rm_fenced, base=path)
    res.path = path
    return res

# %% ../nbs/04_md_hier.ipynb #e39f3f37
class Links(L):
    "A list of `Link` rows, displayed one per line"
    def __repr__(self): return '\n'.join(map(repr, self))

@patch
def links(self:HeadingDict,
    pat='', # Case-insensitive regex matched against each link's text, target, and tail
):
    "This section's `Link` rows, numbered document-wide, filtered by `pat`"
    ls = [l for l in self.root._links if self.start_line <= l.line <= self.end_line]
    if pat:
        r = re.compile(pat, re.IGNORECASE)
        ls = [l for l in ls if r.search(l.txt) or r.search(l.url) or r.search(l.tail)]
    return Links(ls)

# %% ../nbs/04_md_hier.ipynb #e0d49d34
@patch
def follow(self:HeadingDict,
    n, # A link number, as shown by `links`
):
    "The target text of link `n`: fetched for http(s) targets, read from disk for local ones (resolved against `base`)"
    ls = self.root._links
    if not 1 <= n <= len(ls): raise IndexError(f"Link {n} is not in 1..{len(ls)}")
    url = ls[n-1].url
    base = getattr(self.root, 'base', None)
    if not re.match(r'https?://', url):
        if base is None: raise ValueError(f"{url!r} is relative and this document has no `base`; pass `base=` to `create_heading_dict`")
        if isinstance(base, Path): return (base.parent/url).read_text()
        url = urljoin(str(base), url)
    r = httpx.get(url, follow_redirects=True)
    r.raise_for_status()
    return r.text
